'use strict';
const KEY='toolbox-voyage-ready-v1';
const HISTORY_KEY='toolbox-voyage-history-v1';
const defaults={requirements:[['STCW Basic Safety Training',false],['Medical Certificate (PEME)',false],['Company-required training',false],['Passport validity',false],['Visa (if applicable)',false],['Joining instructions',false]],packing:[['Toothbrush',1],['Toothpaste',3],['Soap',6],['Shampoo',2],['Deodorant',2],['Socks',10]],embarkation:[['Flight itinerary',false],['Joining instructions',false],['Passport',false],['Seaman’s book',false],['Medical certificate',false]],disembarkation:[['Sea service certificate',false],['Crew appraisal',false],['Sign-off clearance',false],['Return flight details',false]]};
const state={tab:'home',page:'home',voyage:load()};
function load(){try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}}
function save(){localStorage.setItem(KEY,JSON.stringify(state.voyage));}
function voyageHistory(){try{const v=JSON.parse(localStorage.getItem(HISTORY_KEY));return Array.isArray(v)?v.filter(x=>x&&typeof x==='object'):[]}catch{return []}}
function archiveCompletedVoyage(p){if(!p||p.stage!=='completed')return true;const entries=voyageHistory();const id=p.archiveId||('voyage-'+Date.now()+'-'+Math.random().toString(36).slice(2,8));const record=JSON.parse(JSON.stringify({...p,archiveId:id}));const index=entries.findIndex(x=>x.archiveId===id);if(index>=0)entries[index]=record;else entries.unshift(record);try{localStorage.setItem(HISTORY_KEY,JSON.stringify(entries));p.archiveId=id;save();return true}catch(e){alert('Unable to save voyage history. Storage may be full. Your current voyage has not been replaced.');return false}}
function formatVoyageDate(s){if(!s)return 'Not recorded';const d=new Date(s);return Number.isNaN(d.getTime())?'Not recorded':d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'})}
function historyCards(){const entries=voyageHistory();return `<div class="card voyage-history"><div class="hero-top"><div class="grow"><h2>Previous Voyages</h2><p class="muted">Completed contracts saved on this device</p></div><span class="badge">${entries.length}</span></div>${entries.length?entries.slice(0,3).map(x=>`<button class="history-row" data-history-id="${escapeHTML(x.archiveId||'')}"><span class="grow"><strong>${escapeHTML(x.vessel||'Unnamed vessel')}</strong><small>Joined ${escapeHTML(x.joining||'Not recorded')} · Signed off ${formatVoyageDate(x.signedOffAt)}</small></span><span>›</span></button>`).join(''):'<p class="muted">Your completed voyages will appear here after you confirm sign-off.</p>'}${entries.length?'<button class="btn secondary full" data-open="voyage-history">View All Voyages</button>':''}</div>`}
function voyageHistoryPage(){const entries=voyageHistory();return `<button class="back" data-open="voyage">← Voyage Ready</button><h1>Previous Voyages</h1><p class="muted">History is stored on this device only. Keep a separate backup before clearing browser data.</p><div class="card">${entries.length?entries.map(x=>`<button class="history-row" data-history-id="${escapeHTML(x.archiveId||'')}"><span class="grow"><strong>${escapeHTML(x.vessel||'Unnamed vessel')}</strong><small>Joined ${escapeHTML(x.joining||'Not recorded')} · Signed off ${formatVoyageDate(x.signedOffAt)}</small></span><span>›</span></button>`).join(''):'<p>No completed voyages yet.</p>'}</div>`}
function voyageHistoryDetail(){const p=voyageHistory().find(x=>x.archiveId===state.historyId);if(!p)return voyageHistoryPage();const labels={requirements:'Predeparture',packing:'Packing',embarkation:'Embarkation',disembarkation:'Disembarkation'};return `<button class="back" data-open="voyage-history">← Previous Voyages</button><h1>${escapeHTML(p.vessel||'Completed Voyage')}</h1><div class="card"><p><b>Status:</b> Completed</p><p><b>Joined:</b> ${escapeHTML(p.joining||'Not recorded')}</p><p><b>Signed off:</b> ${formatVoyageDate(p.signedOffAt)}</p><p><b>Contract duration:</b> ${Number(p.months)||'Not recorded'} months</p><p><b>Readiness at boarding:</b> ${Number.isFinite(p.boardingReadiness)?p.boardingReadiness+'%':'Not recorded'}</p></div>${Object.entries(labels).map(([key,label])=>`<div class="card"><h2>${label} · ${progress(p[key]||[])}%</h2>${(p[key]||[]).map(item=>`<div class="history-item"><span>${item.na?'N/A':item.done?'✓':'○'}</span><span>${escapeHTML(item.name||'Item')}${key==='packing'?' · Qty '+Number(item.qty||0):''}</span></div>`).join('')}</div>`).join('')}`}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function progress(items){if(!items?.length)return 0;const applicable=items.filter(x=>!x.na);return applicable.length?Math.round(applicable.filter(x=>x.done).length/applicable.length*100):100;}
function ring(n){return `<div class="ring" style="--pct:${n}" data-pct="${n}%" aria-label="${n}% complete"></div>`}
function navigate(page){state.page=page;render();window.scrollTo(0,0)}
function sectionRow(id,label){const p=state.voyage;return `<div class="row" role="button" tabindex="0" data-open="${id}"><span style="font-size:24px;color:#007454">${{requirements:'▤',packing:'▣',embarkation:'✈',disembarkation:'⚑'}[id]}</span><span class="grow"><b>${label}</b><div class="muted">${p[id].filter(x=>x.done).length} of ${p[id].length} completed</div></span>${ring(progress(p[id]))}<span>›</span></div>`}
const serviceGroups=[
 {title:'Maritime Services',items:[['MARINA','⚓','https://marina.gov.ph'],['MISMO','▣',null],['Online Appointment','▦',null]]},
 {title:'PEME Clinics',items:[['SuperCare','✚',null],['YGEIA','✚',null],['Nordic','✚',null]]},
 {title:'OFW Services',items:[['DMW','▤','https://dmw.gov.ph'],['OWWA','✦','https://owwa.gov.ph'],['PhilHealth','✚','https://www.philhealth.gov.ph'],['SSS','▥','https://www.sss.gov.ph'],['Pag-IBIG','⌂','https://www.pagibigfund.gov.ph'],['OFBank','₱',null]]},
 {title:'Training Centers',items:[['CREST','⚙',null],['EXACT','⚙',null]]},
 {title:'Manning Agencies',items:[['Pascor','⚓',null],['Capital Shipping','⚓',null],['BSM','⚓',null],['JPhil','⚓',null],['Knutsen','⚓',null]]},
 {title:'Document Services',items:[['Passport','▣','https://www.passport.gov.ph'],['NBI Clearance','▤','https://clearance.nbi.gov.ph'],['PSA','▥','https://psa.gov.ph']]}];
const categoryIcons=['⚓','✚','◉','🎓','🚢','▣'];
function servicesMarkup(){return `<div class="directory-heading"><h2>Seafarer Services</h2><span class="muted">Swipe to explore →</span></div><div class="category-scroll" aria-label="Service categories">${serviceGroups.map((g,gi)=>`<button class="category-tile" data-directory="${gi}" aria-label="Open ${escapeHTML(g.title)}"><span class="category-icon color-${gi}">${categoryIcons[gi]}</span><span class="category-name">${escapeHTML(g.title)}</span></button>`).join('')}</div>`}
function directoryPage(gi){const g=serviceGroups[gi];if(!g)return home();return `<button class="back" data-open="home">← Home</button><div class="service-page-banner"><span class="service-page-symbol">${categoryIcons[gi]}</span><h1>${escapeHTML(g.title)}</h1><p>Find services and official portals</p></div><div class="search-wrap directory-search"><span aria-hidden="true">⌕</span><input id="directorySearch" placeholder="Search ${escapeHTML(g.title)}..." aria-label="Search ${escapeHTML(g.title)}"></div><div class="service-list">${g.items.map(([name,icon,url],i)=>`<button class="service-list-card" data-service="${gi}:${i}"><span class="service-list-icon color-${gi}">${icon}</span><span class="service-list-copy"><strong>${escapeHTML(name)}</strong><small>${url?'Open service website':'Website verification pending'}</small></span><span class="service-list-arrow">›</span></button>`).join('')}</div><p class="directory-disclaimer">Toolbox is independent and not affiliated with these providers. Verify service details with the provider.</p>`}
function serviceDialog(gi,idx){const group=serviceGroups[gi], item=group?.items[idx];if(!item)return;const [name,,url]=item;openModal(`<h2>${escapeHTML(name)}</h2><p class="muted">${escapeHTML(group.title)}</p>${url?`<p>Open the service website in a new tab. Confirm the current service details directly with the provider.</p><a class="btn full service-link" href="${url}" target="_blank" rel="noopener noreferrer">Open website ↗</a>`:`<p>This provider's official direct link has not yet been verified. We will add it after checking the correct website.</p><button class="btn secondary full" type="button" disabled>Link pending verification</button>`}`)}
function safeLocal(key){try{return JSON.parse(localStorage.getItem(key))}catch{return null}}
function dashboardCards(){
 // No fabricated metrics: the legacy app's exam and document stores are not integrated yet.
 const exams=safeLocal('toolbox2-exam-summary');
 const docs=docSummary();
 const examValid=exams&&Number.isFinite(exams.average)&&Number.isFinite(exams.attempts)&&exams.attempts>0;
 const docValid=docs&&Number.isFinite(docs.expiring)&&Number.isFinite(docs.expired);
 return `<section class="dashboard-section"><div class="section-title"><h2>Your Dashboard</h2></div><div class="dashboard-grid"><button class="metric-card exam" data-open="learn" aria-label="Open exam performance"><span class="metric-icon">▤</span><span class="metric-label">EXAM PERFORMANCE</span><strong class="metric-number">${examValid?`${Math.round(exams.average)}%`:'—'}</strong><span class="metric-description">${examValid?`${exams.attempts} exams taken`:'No linked exam results yet'}</span><span class="metric-action">View Results ›</span></button><button class="metric-card documents" data-open="documents" aria-label="Open document status"><span class="metric-icon">▣</span><span class="metric-label">DOCUMENT STATUS</span><strong class="metric-number">${docValid?docs.expiring:'—'}</strong><span class="metric-description">${docValid?`Expiring soon · ${docs.expired} expired`:'Connect document records'}</span><span class="metric-action">Review Documents ›</span></button></div></section>`;
}
function continueSection(){const p=state.voyage;return `<section class="resume-section"><div class="section-title"><h2>Continue Where You Left Off</h2></div>${p?`<button class="resume-card" data-open="voyage"><span class="resume-symbol">⚓</span><span class="grow"><b>Voyage Ready</b><small>${escapeHTML(p.vessel)} · Continue checklist</small></span>${ring(stagePercent(p))}<span class="chevron">›</span></button>`:`<div class="card resume-empty"><b>Ready for your next voyage?</b><p class="muted">Create your first contract checklist to pick up where you left off.</p><button class="btn secondary" data-open="voyage">Get Started →</button></div>`}<button class="resume-card" data-open="learn"><span class="resume-symbol learn">▤</span><span class="grow"><b>OIC Review & OLP</b><small>Open your learning modules</small></span><span class="chevron">›</span></button></section>`}
function ecosystemAndRating(){const rating=Number(localStorage.getItem('toolbox2-feedback-rating'))||0;return `<section class="ecosystem-card"><span class="ecosystem-kicker">BULLETPROOF SEAFARER</span><h2>Three Apps. One Crew.</h2><p>Your Seafaring Life. In Your Pocket.</p><div class="ecosystem-apps"><span>Quebec Fit</span><span>Project Gangway</span><span>Toolbox</span></div><strong class="coming-soon">Ecosystem access · Coming Soon</strong></section><section class="rating-card"><div class="rating-symbol">♡</div><div><h2>Enjoying Toolbox?</h2><p>Help us build a better maritime companion.</p></div><div class="rating-stars" role="group" aria-label="Rate Toolbox from 1 to 5">${[1,2,3,4,5].map(n=>`<button data-rating="${n}" aria-label="Rate ${n} out of 5" aria-pressed="${n===rating}">${n<=rating?'★':'☆'}</button>`).join('')}</div><small>${rating?'Thanks for your feedback!':'Tap a star to save your rating on this device.'}</small></section>`}
const TIME_ZONES=[['Manila, Philippines','Asia/Manila'],['Oslo, Norway','Europe/Oslo'],['London, United Kingdom','Europe/London'],['Singapore','Asia/Singapore'],['Tokyo, Japan','Asia/Tokyo'],['Dubai, UAE','Asia/Dubai'],['New York, USA','America/New_York'],['Los Angeles, USA','America/Los_Angeles'],['Rotterdam, Netherlands','Europe/Amsterdam'],['Mumbai, India','Asia/Kolkata'],['Sydney, Australia','Australia/Sydney'],['UTC / GMT','UTC'],['Ship time UTC−12','Etc/GMT+12'],['Ship time UTC−11','Etc/GMT+11'],['Ship time UTC−10','Etc/GMT+10'],['Ship time UTC−9','Etc/GMT+9'],['Ship time UTC−8','Etc/GMT+8'],['Ship time UTC−7','Etc/GMT+7'],['Ship time UTC−6','Etc/GMT+6'],['Ship time UTC−5','Etc/GMT+5'],['Ship time UTC−4','Etc/GMT+4'],['Ship time UTC−3','Etc/GMT+3'],['Ship time UTC−2','Etc/GMT+2'],['Ship time UTC−1','Etc/GMT+1'],['Ship time UTC+1','Etc/GMT-1'],['Ship time UTC+2','Etc/GMT-2'],['Ship time UTC+3','Etc/GMT-3'],['Ship time UTC+4','Etc/GMT-4'],['Ship time UTC+5','Etc/GMT-5'],['Ship time UTC+6','Etc/GMT-6'],['Ship time UTC+7','Etc/GMT-7'],['Ship time UTC+8','Etc/GMT-8'],['Ship time UTC+9','Etc/GMT-9'],['Ship time UTC+10','Etc/GMT-10'],['Ship time UTC+11','Etc/GMT-11'],['Ship time UTC+12','Etc/GMT-12'],['Ship time UTC+13','Etc/GMT-13'],['Ship time UTC+14','Etc/GMT-14']];
const CLOCK_KEY='toolbox2-world-clocks-v1';
function clockSelection(){let v={left:'Asia/Manila',right:'Europe/Oslo'};try{const x=JSON.parse(localStorage.getItem(CLOCK_KEY));if(x&&typeof x==='object')v={...v,...x}}catch{}return v}
function zoneOffset(zone,now){const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'longOffset'}).formatToParts(now);const x=parts.find(p=>p.type==='timeZoneName')?.value||'GMT';const m=x.match(/GMT([+-])(\d{1,2})(?::(\d{2}))?/);return m?(m[1]==='-'?-1:1)*(Number(m[2])*60+Number(m[3]||0)):0}
function offsetLabel(minutes){if(minutes===0)return 'GMT+0';return 'GMT'+(minutes<0?'−':'+')+String(Math.floor(Math.abs(minutes)/60))+(Math.abs(minutes)%60?':'+String(Math.abs(minutes)%60).padStart(2,'0'):'')}
function clockMarkup(){const sel=clockSelection();return `<section class="world-time"><div class="section-title"><h2>World Time</h2><small>Home & vessel time</small></div><div class="world-time-grid">${['left','right'].map((side)=>`<div class="world-clock"><label for="clock-${side}">${side==='left'?'HOME TIME':'VESSEL / LOCAL TIME'}</label><select id="clock-${side}" data-clock-zone="${side}" aria-label="${side==='left'?'Home':'Vessel or local'} time zone">${TIME_ZONES.map(([label,zone])=>`<option value="${zone}" ${sel[side]===zone?'selected':''}>${escapeHTML(label)}</option>`).join('')}</select><strong id="clock-time-${side}" aria-live="off">--:--</strong><span class="clock-date" id="clock-date-${side}">Loading...</span><span class="clock-offset" id="clock-offset-${side}">GMT</span></div>`).join('')}<span class="clock-difference" id="clock-difference">TIME DIFFERENCE</span></div><p class="clock-note">Times follow your device clock. Choose ship time manually when needed.</p></section>`}
function refreshClocks(){if(!document.getElementById('clock-time-left'))return;const sel=clockSelection(),now=new Date();for(const side of ['left','right']){const zone=sel[side];try{document.getElementById('clock-time-'+side).textContent=new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now);document.getElementById('clock-date-'+side).textContent=new Intl.DateTimeFormat('en-GB',{timeZone:zone,weekday:'short',day:'numeric',month:'short'}).format(now);document.getElementById('clock-offset-'+side).textContent=offsetLabel(zoneOffset(zone,now))}catch{document.getElementById('clock-time-'+side).textContent='Unavailable'}}try{const diff=zoneOffset(sel.left,now)-zoneOffset(sel.right,now),hours=Math.floor(Math.abs(diff)/60),mins=Math.abs(diff)%60;document.getElementById('clock-difference').textContent=diff===0?'SAME TIME':`TIME DIFFERENCE: ${hours}h${mins?' '+mins+'m':''}`}catch{}}
function voyageStage(p){return p?.stage==='onboard'||p?.stage==='completed'?p.stage:'preparing'}
function readiness(p){return p?Math.round((progress(p.requirements)+progress(p.packing)+progress(p.embarkation))/3):0}
function stagePercent(p){return voyageStage(p)==='preparing'?readiness(p):progress(p.disembarkation)}
function lifecycleActions(p){if(!p)return '';const stage=voyageStage(p);if(stage==='completed')return '<p class="muted">This contract is completed. Start a new voyage when ready.</p>';if(stage==='preparing')return `<button type="button" class="btn secondary full" id="confirmBoarding">Confirm I'm Onboard</button>`;return `<button type="button" class="btn secondary full" id="confirmSignoff">Confirm Sign-Off</button>`}
function home(){const p=state.voyage,stage=voyageStage(p),percent=stagePercent(p),title=stage==='preparing'?'Voyage Ready':stage==='onboard'?'Disembarkation Ready':'Contract Completed',subtitle=stage==='preparing'?'Prepare for your next contract':stage==='onboard'?'You’re onboard. Prepare for sign-off.':'Your voyage has been completed';return `<section class="home-banner"><div class="greeting"><span>Good day,</span><h1>Seafarer!</h1><p>Your Maritime Companion</p></div><img class="home-mascot" src="assets/toolbox-spanner.png" alt="Toolbox wrench mascot" onerror="this.src='assets/seafarer-mascot.webp'"></section><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" placeholder="Search services, documents, learning..." aria-label="Search Toolbox"></div><div class="card hero voyage-card"><div class="hero-top"><div class="grow"><h2>${title}</h2><p class="muted">${subtitle}</p><p class="voyage-count">⚓ ${p?escapeHTML(p.vessel):'Your next contract starts here'}</p></div>${ring(percent)}</div><button class="btn full lime" data-open="voyage">${p?'View Voyage':'Prepare for My Next Contract'} →</button>${lifecycleActions(p)}</div>${clockMarkup()}${servicesMarkup()}${dashboardCards()}${continueSection()}${ecosystemAndRating()}<footer>Developed by Bulletproof Seafarer<br>Independent tool · Not a government service</footer>`}

function voyage(){const p=state.voyage;if(!p)return `<button class="back" data-open="home">← Home</button><h1>Voyage Ready</h1><p class="muted">Prepare for your next contract with checklists you control.</p><div class="card"><label class="field">Vessel name<input id="vessel" placeholder="e.g. MV Explorer"></label><label class="field">Joining date<input id="joining" type="date"></label><label class="field">Contract duration <span id="monthsLabel">6 months</span><input id="months" type="range" min="1" max="12" value="6"></label><button class="btn full" id="startVoyage">Create My Voyage</button></div>${historyCards()}`;const stage=voyageStage(p),pct=stagePercent(p),title=stage==='preparing'?'Embarkation readiness':stage==='onboard'?'Disembarkation readiness':'Contract completed';return `<button class="back" data-open="home">← Home</button><h1>${stage==='preparing'?'Voyage Ready':stage==='onboard'?'Onboard · Sign-Off Preparation':'Completed Voyage'}</h1><div class="card"><div class="hero-top">${ring(pct)}<div class="grow"><b>${title}</b><p class="muted">${escapeHTML(p.vessel)} · ${escapeHTML(p.joining||'Date not set')} · ${p.months} months</p></div></div><p class="muted">${stage==='preparing'?'Progress is self-reported, not official clearance.':stage==='onboard'?`Your embarkation readiness was ${p.boardingReadiness??readiness(p)}% when you confirmed boarding.`:'Your completed checklists remain available for review.'}</p><button class="btn secondary" id="editVoyage">Edit contract</button>${lifecycleActions(p)}</div><div class="card">${sectionRow('requirements','Predeparture Requirements')}${sectionRow('packing','Packing Checklist')}${sectionRow('embarkation','Embarkation Folder')}${sectionRow('disembarkation','Disembarkation Folder')}</div>${historyCards()}<button class="btn secondary full" id="newVoyage">Prepare Another Contract</button>`}

function checklist(id){const p=state.voyage;const labels={requirements:'Predeparture Requirements',packing:'Packing Checklist',embarkation:'Embarkation Folder',disembarkation:'Disembarkation Folder'};return `<button class="back" data-open="voyage">← Voyage Ready</button><h1>${labels[id]}</h1><div class="card hero-top">${ring(progress(p[id]))}<div class="grow"><b>${p[id].filter(x=>x.done).length} completed</b><p class="muted">Mark items complete as you prepare.</p></div></div>${id==='packing'?`<div class="card"><label class="field">Contract duration: <span id="monthsLabel">${p.months} months</span><input id="months" type="range" min="1" max="12" value="${p.months}"></label><p class="muted">Suggested quantities are editable. Adjust for onboard supplies.</p></div>`:''}<div class="card">${p[id].map((x,i)=>`<div class="row"><input class="check" type="checkbox" data-check="${id}:${i}" ${x.done?'checked':''} aria-label="Complete ${escapeHTML(x.name)}"><span class="grow" style="${x.done?'text-decoration:line-through;color:#81938a':''}">${escapeHTML(x.name)}${x.na?'<small class="badge">N/A</small>':''}</span>${id==='packing'?`<div class="qty"><button data-qty="${i}:-1" aria-label="Reduce ${escapeHTML(x.name)}">−</button><b>${x.qty}</b><button data-qty="${i}:1" aria-label="Increase ${escapeHTML(x.name)}">+</button></div>`:`<button class="btn secondary" data-na="${id}:${i}">${x.na?'Restore':'N/A'}</button>`}<button data-remove="${id}:${i}" aria-label="Remove ${escapeHTML(x.name)}" style="border:0;background:none;color:#aa4c40">×</button></div>`).join('')}</div><button class="btn full" id="addItem">+ Add Custom Item</button>${id==='embarkation'||id==='disembarkation'?'<p class="muted">Document checklist only in this first build. Secure file attachments will be integrated with the existing Documents system.</p>':''}`}

/* Phase 1.7 — Learn UI. Existing learning engine stays in index.html. */
const learnCatalog=[
 {icon:'⚓',title:'OIC Examination',subtitle:'Deck and Engine · Operational level',tag:'Review & Exam',tone:'blue'},
 {icon:'▤',title:'OLP',subtitle:'Operational-level learning and practice',tag:'Study & Practice',tone:'violet'},
 {icon:'◈',title:'Deck',subtitle:'Navigation, cargo and watchkeeping',tag:'Study',tone:'blue'},
 {icon:'⚙',title:'Engine',subtitle:'Machinery, systems and watchkeeping',tag:'Study',tone:'green'},
 {icon:'✹',title:'Safety',subtitle:'LSA, FFE and shipboard safety',tag:'Study',tone:'amber'},
 {icon:'▣',title:'General',subtitle:'Maritime English and career preparation',tag:'Study',tone:'blue'}
];
function learn(){return `<div class="learn-page"><div class="learn-head"><h1>Learn</h1><p>Build your maritime knowledge, one session at a time.</p></div><section class="learn-progress card"><div class="learn-progress-top"><div><span class="learn-eyebrow">YOUR LEARNING PROGRESS</span><h2>Keep learning</h2><p>Progress will appear when existing learning records are connected.</p></div><div class="learn-progress-mark">—</div></div><div class="learn-progress-track"><span style="width:0"></span></div><small>No verified completion summary yet</small></section><div class="learn-mode" role="group" aria-label="Learning mode"><button type="button" class="selected" data-learn-mode="study" aria-pressed="true">Study</button><button type="button" data-learn-mode="exam" aria-pressed="false">Practice / Exam</button></div><div class="learn-section-title"><h2>Learning Library</h2><span>Existing Toolbox content</span></div><div class="learn-feature-grid">${learnCatalog.slice(0,2).map((c,i)=>`<button type="button" class="learn-feature ${c.tone}" data-learn-open="${i}"><span class="learn-feature-icon">${c.icon}</span><strong>${c.title}</strong><small>${c.subtitle}</small><span class="learn-feature-action">Open learning →</span></button>`).join('')}</div><div class="learn-section-title"><h2>Explore Topics</h2></div><div class="learn-topic-grid">${learnCatalog.slice(2).map((c,i)=>`<button type="button" class="learn-topic ${c.tone}" data-learn-open="${i+2}"><span class="learn-topic-icon">${c.icon}</span><strong>${c.title}</strong><small>${c.subtitle}</small></button>`).join('')}</div><div class="learn-info card"><strong>Existing learning materials are preserved</strong><p>OIC, OLP and other available modules currently run in the original Toolbox learning engine. Open a category to continue there; scores and progress are not fabricated on this screen.</p><a href="index.html" class="btn full learn-legacy-link">Open existing Toolbox learning →</a></div></div>`}
function learnOpen(index){const item=learnCatalog[index];if(!item)return;openModal(`<h2>${escapeHTML(item.title)}</h2><p class="muted">${escapeHTML(item.subtitle)}</p><p>Continue using the existing Toolbox learning module. The new Learn screen is a navigation layer; direct deep links and progress synchronization will follow after the original learning routes are verified.</p><a class="btn full learn-legacy-link" href="index.html">Open Toolbox Learning →</a>`)}


// Phase 2.2.1: Non-sensitive document expiry tracker. Never collect ID numbers or images here.
const DOC_RECORDS_KEY='toolbox2-document-records-v1';
function docRecords(){try{const a=JSON.parse(localStorage.getItem(DOC_RECORDS_KEY));return Array.isArray(a)?a.filter(x=>x&&typeof x==='object'):[]}catch{return []}}
function docStatus(x){if(!x.expiry)return 'no-expiry';const today=new Date();const utcToday=Date.UTC(today.getFullYear(),today.getMonth(),today.getDate());const expiry=Date.parse(x.expiry+'T00:00:00Z');if(!Number.isFinite(expiry))return 'no-expiry';const days=Math.ceil((expiry-utcToday)/86400000);return days<0?'expired':days<=365?'expiring':'valid'}
function docSummary(){const all=docRecords(),out={valid:0,expiring:0,expired:0,unknown:0};all.forEach(x=>{const s=docStatus(x);out[s==='no-expiry'?'unknown':s]++});return out}
function saveDocRecords(records){try{localStorage.setItem(DOC_RECORDS_KEY,JSON.stringify(records));return true}catch{alert('Could not save document record. Check browser storage.');return false}}
// Test-only local attachments: IndexedDB blobs are NOT encrypted or cloud-synced.
const PHOTO_DB='toolbox2-document-attachments-test-v1';
function photoDatabase(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(new Error('Photo storage unavailable'));const request=indexedDB.open(PHOTO_DB,1);request.onupgradeneeded=()=>request.result.createObjectStore('photos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function photoOperation(id,action,blob){const db=await photoDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('photos',action==='read'?'readonly':'readwrite'),store=tx.objectStore('photos');const req=action==='read'?store.get(id):action==='delete'?store.delete(id):store.put(blob,id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close();tx.onerror=()=>reject(tx.error)})}
// Phase 2.2.3: multi-side document capture. TEST DATA ONLY; browser blobs are unencrypted.
let pendingDocPhotos={}, activeDocSide='page';
const docSides={id:['front','back'],passport:['page'],seamans:['page'],other:['page']};
function docAttachmentKind(title){const t=title.toLowerCase();return t.includes('passport')?'passport':t.includes('seaman')||t.includes('seafarer book')?'seamans':/\bid\b|license|licence|card/.test(t)?'id':'other'}
function docPhotoSlots(){const kind=document.getElementById('docAttachmentType')?.value||'other';return docSides[kind]||['page']}
function updateDocSlots(){const sides=docPhotoSlots(),box=document.getElementById('docPhotoSlots');if(!box)return;const cameraIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 8V6a2 2 0 0 1 2-2h2M16 4h2a2 2 0 0 1 2 2v2M20 16v2a2 2 0 0 1-2 2h-2M8 20H6a2 2 0 0 1-2-2v-2"/><path d="M8 9h2l1-1h3l1 1h2v8H8z"/><circle cx="12.5" cy="13" r="2"/></svg>';const photoIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m4 17 5-5 3 3 3-4 5 6"/></svg>';box.innerHTML=sides.map(side=>`<div class="doc-side-card doc-side-card--compact"><div class="doc-side-heading">${side==='front'?'Front of ID':side==='back'?'Back of ID':'Document image'} <span class="doc-optional">(optional)</span></div><div class="doc-photo-actions doc-photo-actions--compact"><button type="button" class="doc-camera-tile" data-pick-doc-photo="camera" data-photo-side="${side}" aria-label="Take photo of ${side}">${cameraIcon}</button><button type="button" class="doc-gallery-tile" data-pick-doc-photo="gallery" data-photo-side="${side}">${photoIcon}<span>Choose from photos</span></button></div><button type="button" class="doc-file-link" data-pick-doc-photo="files" data-photo-side="${side}">Or choose a file / PDF</button><p class="muted doc-photo-info" id="docPhotoInfo-${side}">${pendingDocPhotos[side] instanceof Blob?'Selected: '+escapeHTML(pendingDocPhotos[side].name||'image'):'No new attachment selected'}</p><div class="doc-side-actions"><button type="button" class="btn secondary" data-view-doc-side="${side}">View saved</button><button type="button" class="btn secondary" data-remove-doc-side="${side}">Remove</button></div></div>`).join('');}
function chooseDocumentPhoto(source,side){activeDocSide=side||'page';const input=document.getElementById('docPhotoInput');if(!input)return;input.value='';input.accept=source==='files'?'image/*,application/pdf':'image/*';if(source==='camera')input.setAttribute('capture','environment');else input.removeAttribute('capture');input.click()}
function showPhotoSelection(file){const info=document.getElementById('docPhotoInfo-'+activeDocSide);if(info)info.textContent=file?file.name+' · '+Math.round(file.size/1024)+' KB (pending save)':'No attachment selected'}
function openAttachmentBlob(blob){const url=URL.createObjectURL(blob),win=window.open(url,'_blank','noopener,noreferrer');if(!win){const a=document.createElement('a');a.href=url;a.download=blob.type==='application/pdf'?'document.pdf':'document-image';a.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function viewDocumentPhoto(id,side){try{const blob=pendingDocPhotos[side] instanceof Blob?pendingDocPhotos[side]:await photoOperation(id+'::'+side,'read')||(side==='page'?await photoOperation(id,'read'):null);if(!blob){alert('No saved attachment for this side.');return}openAttachmentBlob(blob)}catch(e){alert('Unable to open this attachment. Please try again.')}}
function docRecordEditor(id){pendingDocPhotos={};const record=docRecords().find(x=>x.id===id)||{category:'personal',title:'',issued:'',expiry:''};const kind=record.attachmentKind||docAttachmentKind(record.title);openModal(`<h2>${id?'Edit':'Add'} Document</h2><p class="muted">TEST ONLY: attachments are stored unencrypted in this browser. Use dummy documents, not real IDs, passports or medical records.</p><label class="field">Category<select id="docCategory">${documentSections.filter(x=>['personal','certificates','medical'].includes(x[0])).map(x=>`<option value="${x[0]}" ${record.category===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label class="field">Document name<input id="docTitle" maxlength="80" placeholder="e.g. Passport" value="${escapeHTML(record.title)}"></label><label class="field">Issue date (optional)<input id="docIssued" type="date" value="${escapeHTML(record.issued||'')}"></label><label class="field">Expiry date (optional)<input id="docExpiry" type="date" value="${escapeHTML(record.expiry||'')}"></label><div class="doc-photo-picker doc-photo-picker--compact"><label class="field doc-format-field">Image type<select id="docAttachmentType"><option value="id" ${kind==='id'?'selected':''}>ID card — front and back</option><option value="passport" ${kind==='passport'?'selected':''}>Passport — full page</option><option value="seamans" ${kind==='seamans'?'selected':''}>Seaman's Book — full page</option><option value="other" ${kind==='other'?'selected':''}>Other — full page</option></select></label><div id="docPhotoSlots"></div><input id="docPhotoInput" type="file" accept="image/*,application/pdf" hidden></div><p class="muted" id="docEditorError" role="alert"></p><button type="button" class="btn full" data-save-doc="${escapeHTML(id||'new')}">Save Document</button>${id?`<button type="button" class="btn secondary full" data-delete-doc="${escapeHTML(id)}">Delete Document</button>`:''}`);updateDocSlots()}
function docRecordsMarkup(category){const rows=docRecords().filter(x=>x.category===category);return `<div class="docs-record-list">${rows.length?rows.map(x=>`<button type="button" class="docs-record" data-edit-doc="${escapeHTML(x.id)}"><span><strong>${escapeHTML(x.title)}</strong><small>${x.expiry?'Expires '+escapeHTML(x.expiry):'No expiry date'}</small></span><span class="docs-record-status ${docStatus(x)}">${({valid:'Valid',expiring:'Renew within 1 year',expired:'Expired','no-expiry':'No expiry'})[docStatus(x)]}</span></button>`).join(''):'<p class="muted">No documents recorded in this category yet.</p>'}</div>`}

const documentSections=[
 ['personal','Personal Documents','Passport, Seaman’s Book, visas','▣'],
 ['certificates','Maritime Certificates','STCW, licenses and endorsements','⚓'],
 ['medical','Medical Documents','PEME and medical records','✚'],
 ['sea-service','Sea Service Records','Vessels, ranks and sign-on / sign-off','▤']
];
const quickIdTypes=[['passport','Passport Number'],['seamans','Seaman’s Book Number'],['sss','SSS Number'],['pagibig','Pag-IBIG MID'],['philhealth','PhilHealth PIN'],['tin','TIN'],['marina','MARINA SRN'],['other','Other Identification']];
function documents(){const s=docSummary();return `<div class="docs-page"><div class="docs-entry-wordmark" aria-label="Seafarer Documents">Seafarer <strong>Documents</strong></div><div class="docs-head docs-hero"><div class="docs-hero-content"><span class="docs-hero-kicker">YOUR MARITIME VAULT</span><h1>Documents</h1><p>Keep your maritime requirements organized, and stay ahead of expiry dates.</p><span class="docs-hero-chip">PRIVATE TEST PREVIEW</span></div><div class="docs-hero-art" aria-hidden="true"><svg viewBox="0 0 180 180" fill="none"><circle cx="95" cy="85" r="73" stroke="white" stroke-opacity=".18" stroke-width="1.5"/><circle cx="95" cy="85" r="52" stroke="white" stroke-opacity=".14"/><rect x="51" y="37" width="93" height="113" rx="13" fill="#D7F5E9" transform="rotate(10 51 37)"/><rect x="51" y="37" width="93" height="113" rx="13" stroke="white" stroke-width="3" transform="rotate(10 51 37)"/><path d="M81 66h35M77 82h39M73 98h39" stroke="#138269" stroke-width="5" stroke-linecap="round"/><circle cx="103" cy="119" r="15" fill="#0B765A" stroke="#E7FFF5" stroke-width="4"/><path d="m97 119 4 4 8-9" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></div></div><div class="docs-status"><div class="docs-status-tile valid"><b>${s.valid}</b><span>Valid</span></div><div class="docs-status-tile soon"><b>${s.expiring}</b><span>Renew within 1 year</span></div><div class="docs-status-tile expired"><b>${s.expired}</b><span>Expired</span></div></div><p class="docs-note">${s.unknown} record(s) without an expiry date. Renewal preparation starts 365 days before expiry. Stored only on this preview URL.</p><section class="docs-cv-feature"><div class="docs-cv-copy"><span class="docs-cv-label">MARITIME CAREER TOOLS</span><h2>Build your Maritime CV</h2><p>Prepare a professional seafarer resume using the existing Toolbox CV builder.</p><button type="button" class="docs-cv-button" data-doc-section="cv">Explore CV Builder <span aria-hidden="true">→</span></button></div><div class="docs-cv-art" aria-hidden="true"><span class="docs-cv-paper"><i></i><i></i><i></i><i></i></span><span class="docs-cv-seal">✓</span></div></section><div class="docs-section-title"><h2>Document dashboard</h2><span>Renewal overview</span></div><div class="docs-tabbar" aria-label="Document sections"><button type="button" class="docs-tab active" data-doc-section="all">All records</button><button type="button" class="docs-tab" data-doc-section="sea-service">Sea service</button><button type="button" class="docs-tab" data-doc-section="ids">IDs</button></div><button type="button" class="btn full" id="addDocRecord">+ Add Document</button><div class="docs-section-title"><h2>Document records</h2><span>${docRecords().length} saved</span></div><div class="docs-record-list">${docRecords().length?docRecords().map(x=>`<button type="button" class="docs-record" data-edit-doc="${escapeHTML(x.id)}"><span><strong>${escapeHTML(x.title)}</strong><small>${x.expiry?`Expires ${escapeHTML(x.expiry)}`:"No expiry date"}</small></span><span class="docs-record-status ${docStatus(x)}">${({valid:"Valid",expiring:"Renew soon",expired:"Expired","no-expiry":"No expiry"})[docStatus(x)]}</span></button>`).join(""):`<p class="muted">No records yet. Add your first document above.</p>`}</div><div class="docs-links">${documentSections.map(([id,title,subtitle,icon])=>`<button class="docs-link" data-doc-section="${id}"><span class="docs-link-icon">${icon}</span><span><strong>${title}</strong><small>${subtitle}</small></span><span class="docs-arrow">›</span></button>`).join('')}<button class="docs-link" data-doc-section="cv"><span class="docs-link-icon">▤</span><span><strong>Generate Maritime CV</strong><small>Create and export your maritime CV</small></span><span class="docs-arrow">›</span></button></div><div class="docs-section-title"><h2>Quick ID Cards</h2><span>Secure integration pending</span></div><p class="docs-note">Identification numbers are not collected in this preview.</p><div class="quick-id-grid">${quickIdTypes.map(([id,label])=>`<button class="quick-id" data-quick-id="${id}"><span class="quick-id-symbol">▣</span><strong>${label}</strong><span>Not connected</span><small>View details ›</small></button>`).join('')}</div><div class="docs-privacy">ID number entry remains disabled until secure storage is available.</div><button type="button" class="btn secondary full" id="exportDocRecords">Export document tracker backup</button><a class="btn full docs-original" href="index.html">Open existing Toolbox Documents →</a></div>`}
function documentSpecialPage(id){if(id==='all'){return `<button class="back" data-open="documents">← Documents dashboard</button><div class="docs-head"><h1>All Document Records</h1><p>All saved document records in one place.</p></div><button type="button" class="btn full" id="addDocRecord">+ Add Document</button><div class="docs-record-list">${docRecords().length?docRecords().map(x=>`<button class="docs-record" data-edit-doc="${escapeHTML(x.id)}"><span><strong>${escapeHTML(x.title)}</strong><small>${escapeHTML(x.category)} · ${x.expiry?'Expires '+escapeHTML(x.expiry):'No expiry date'}</small></span><span class="docs-record-status ${docStatus(x)}">${({valid:'Valid',expiring:'Renew soon',expired:'Expired','no-expiry':'No expiry'})[docStatus(x)]}</span></button>`).join(''):'<p class="muted">No documents recorded yet.</p>'}</div>`}if(id==='ids'){return `<button class="back" data-open="documents">← Documents dashboard</button><div class="docs-head"><h1>IDs & Identification</h1><p>Review ID document records. Sensitive ID numbers are not collected in this test version.</p></div><button type="button" class="btn full" id="addDocRecord">+ Add ID Document</button><div class="docs-record-list">${docRecords().filter(x=>x.attachmentKind==='id').map(x=>`<button class="docs-record" data-edit-doc="${escapeHTML(x.id)}"><span><strong>${escapeHTML(x.title)}</strong><small>Front / back attachment</small></span><span class="docs-record-status ${docStatus(x)}">${docStatus(x)==='expiring'?'Renew soon':docStatus(x)}</span></button>`).join('')||'<p class="muted">No ID records yet. Select ID card format when adding a document.</p>'}</div>`}return null}
function documentSectionPage(id){const special=documentSpecialPage(id);if(special)return special;const item=documentSections.find(x=>x[0]===id);const title=id==='cv'?'Maritime CV':item?.[1];if(!title)return documents();const tracked=['personal','certificates','medical'].includes(id);return `<button class="back" data-open="documents">← Documents</button><div class="docs-head"><h1>${title}</h1><p>${tracked?'Manage document names, expiry dates, and test attachments. No ID numbers are collected.':'This section still uses the existing Toolbox application.'}</p></div>${tracked?`${docRecordsMarkup(id)}<button type="button" class="btn full" data-add-doc-category="${id}">+ Add ${title}</button>`:`<div class="card docs-interim"><strong>Existing feature preserved</strong><p class="muted">Direct integration is not yet available.</p><a class="btn full docs-original" href="index.html">Open existing Toolbox →</a></div>`}`}
function quickIdDetail(id){const item=quickIdTypes.find(x=>x[0]===id);if(!item)return;openModal(`<h2>${escapeHTML(item[1])}</h2><p class="muted">No secure ID record is connected yet.</p><p>For your privacy, this preview does not collect, store, or copy identification numbers. Once connected to secure storage, this card will support masked display, reveal, and copy.</p><button type="button" class="btn secondary full" id="closeQuickId">Close</button>`)}
function legacy(title,description){return `<h1>${title}</h1><p class="muted">${description}</p><div class="card"><h3>Existing Toolbox modules</h3><p>Access the original working app while we migrate its features into the new design.</p><a class="btn" style="display:inline-block;text-decoration:none" href="index.html">Open existing Toolbox →</a></div>`}
function createMenu(){return `<div class="create-menu"><div class="create-menu-head"><span class="create-menu-badge">＋</span><div><h2>Quick Create</h2><p>What would you like to add?</p></div></div><div class="create-actions"><button type="button" class="create-action" data-create-action="voyage"><span class="create-action-icon green">⚓</span><span><strong>New Voyage</strong><small>Prepare for your next contract</small></span><span class="create-arrow">›</span></button><button type="button" class="create-action" data-create-action="document"><span class="create-action-icon blue">▣</span><span><strong>Add Document</strong><small>Open personal and maritime document records</small></span><span class="create-arrow">›</span></button><button type="button" class="create-action" data-create-action="sea-service"><span class="create-action-icon teal">▤</span><span><strong>Add Sea Service</strong><small>Record vessel, rank and service dates</small></span><span class="create-arrow">›</span></button><button type="button" class="create-action" data-create-action="cv"><span class="create-action-icon amber">◫</span><span><strong>Create Maritime CV</strong><small>Open your existing CV generator</small></span><span class="create-arrow">›</span></button><button type="button" class="create-action" data-create-action="quick-id"><span class="create-action-icon violet">▣</span><span><strong>Add Quick ID</strong><small>Secure ID entry is not available yet</small></span><span class="create-arrow">›</span></button></div><p class="create-footnote">Existing records are preserved. Secure ID storage and direct document entry are being integrated.</p></div>`}
function handleCreateAction(action){closeModal();if(action==='voyage'){state.tab='home';navigate('voyage');if(state.voyage){openModal(`<h2>New Voyage</h2><p>You already have a voyage checklist. To start another, use <strong>Prepare Another Contract</strong> on Voyage Ready. This will replace the current local checklist.</p><button type="button" class="btn full" id="closeCreateNotice">View current voyage</button>`)}return}if(action==='quick-id'){state.tab='documents';navigate('documents');openModal(`<h2>Add Quick ID</h2><p>Quick ID cards are available in Documents, but secure number entry is not enabled yet. We won't collect or save sensitive identification numbers in this preview.</p><button type="button" class="btn full" id="closeCreateNotice">View Quick ID Cards</button>`);return}const route={'document':'doc-personal','sea-service':'doc-sea-service','cv':'doc-cv'}[action];if(route){state.tab='documents';navigate(route)}}
// Phase 2.0: Account shell. No personal or authentication secrets are stored here.
function account(){return `<div class="account-page"><div class="account-hero"><div class="account-avatar" aria-hidden="true">♙</div><div><span class="account-kicker">TOOLBOX ACCOUNT</span><h1>My Account</h1><p>Manage your seafaring workspace</p></div></div><section class="account-summary card"><strong>Profile not connected</strong><p>Your name, rank, and department will appear after the existing account system is connected.</p><button type="button" class="account-cta" data-account-page="profile">View profile details →</button></section><h2 class="account-heading">Your workspace</h2><div class="account-list">${[
['profile','♙','My Profile','Name, rank and department'],
['activity','▤','My Activity','Exams and learning history'],
['security','♧','Account & Security','Existing sign-in and account access'],
['preferences','⚙','Preferences','Display and motion settings'],
['privacy','▣','Privacy & Data','Local data and privacy information'],
['help','?','Help & Feedback','Support and suggestions'],
['about','⚓','About Toolbox','Version and Bulletproof Seafarer']
].map(([id,icon,title,description])=>`<button type="button" class="account-link" data-account-page="${id}"><span class="account-link-icon">${icon}</span><span class="account-link-copy"><strong>${title}</strong><small>${description}</small></span><span class="account-chevron">›</span></button>`).join('')}</div><div class="account-brand"><strong>Toolbox</strong><span>Developed by Bulletproof Seafarer</span><small>Your Seafaring Life. In Your Pocket.</small></div></div>`}
function accountSubpage(id){const back='<button type="button" class="back" data-account-back="1">← Account</button>';const head=(title,subtitle)=>`${back}<div class="account-subhead"><h1>${title}</h1><p>${subtitle}</p></div>`;const original='<a class="btn full account-original" href="index.html">Open existing Toolbox →</a>';
switch(id){
case 'profile':return head('My Profile','Seafarer identity and professional details')+`<div class="card account-detail"><strong>Existing profile integration pending</strong><p>Your name, rank, department and vessel information are not collected on this preview screen. Continue using your existing Toolbox profile where available.</p>${original}</div>`;
case 'activity':return head('My Activity','Your maritime learning journey')+`<div class="card account-detail"><strong>Learning and exam history</strong><p>Verified exam scores and study progress will be shown after connecting the existing learning records.</p><button type="button" class="btn full" data-account-go="learn">Open Learn</button></div>`;
case 'security':return head('Account & Security','Manage access to your Toolbox account')+`<div class="card account-detail"><strong>Existing authentication retained</strong><p>This preview does not implement a separate login, password reset or account deletion. Use the original Toolbox account controls where available.</p>${original}</div>`;
case 'preferences':return head('Preferences','Personalize your Toolbox experience')+`<div class="card account-detail"><label class="account-toggle"><span><strong>Reduce animations</strong><small>Limit decorative transitions in this preview</small></span><input type="checkbox" id="accountReduceMotion" ${localStorage.getItem('toolbox2-reduce-motion')==='true'?'checked':''}></label><p class="account-hint">This setting is stored only in this browser. Notifications and appearance preferences will be connected later.</p></div>`;
case 'privacy':return head('Privacy & Data','Know what is saved in this preview')+`<div class="card account-detail"><strong>Local preview data</strong><p>Voyage Ready checklist progress, feedback rating and reduced-motion preference may be stored in this browser. Quick ID numbers are not collected by this preview.</p><p>Secure document sync, data export and account deletion are not implemented here. Do not enter sensitive ID numbers into unverified forms.</p><button type="button" class="account-cta" data-account-page="security">Account access information →</button></div>`;
case 'help':return head('Help & Feedback','Share ideas and report problems')+`<div class="card account-detail"><strong>Help improve Toolbox</strong><p>Report bugs or suggest improvements through your existing Toolbox feedback channel. A direct support form is not yet connected in this preview.</p>${original}</div>`;
case 'about':return head('About Toolbox','Built for the seafaring community')+`<div class="card account-detail account-about"><div class="account-about-mark">⚓</div><h2>Toolbox 2.0</h2><p>Account interface preview · Phase 2.0</p><strong>Developed by Bulletproof Seafarer</strong><small>Your Seafaring Life. In Your Pocket.</small></div>`;
default:return account();}}
function applyAccountPreferences(){document.documentElement.classList.toggle('toolbox-reduced-motion',localStorage.getItem('toolbox2-reduce-motion')==='true')}
function render(){let page=state.page;document.getElementById('view').innerHTML=page==='home'?home():page.startsWith('directory-')?directoryPage(Number(page.split('-')[1])):page==='voyage'?voyage():page==='voyage-history'?voyageHistoryPage():page==='voyage-history-detail'?voyageHistoryDetail():['requirements','packing','embarkation','disembarkation'].includes(page)&&state.voyage?checklist(page):page==='learn'?learn():page==='documents'?documents():page.startsWith('doc-')?documentSectionPage(page.slice(4)):page==='account'?account():page.startsWith('account-')?accountSubpage(page.slice(8)):legacy('Toolbox','Open the original application.');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));refreshClocks();}
function openModal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').showModal()}
function closeModal(){document.getElementById('modal').close()}
document.getElementById('closeToolboxModal').addEventListener('click',closeModal);
document.addEventListener('click',async e=>{const pick=e.target.closest('[data-pick-doc-photo]');if(pick){chooseDocumentPhoto(pick.dataset.pickDocPhoto,pick.dataset.photoSide);return}const view=e.target.closest('[data-view-doc-side]');if(view){viewDocumentPhoto(document.querySelector('[data-save-doc]').dataset.saveDoc,view.dataset.viewDocSide);return}const remove=e.target.closest('[data-remove-doc-side]');if(remove){const side=remove.dataset.removeDocSide;pendingDocPhotos[side]=null;const info=document.getElementById('docPhotoInfo-'+side);if(info)info.textContent='Marked for removal when saved';return}const add=e.target.closest('[data-add-doc-category]');if(add){docRecordEditor();document.getElementById('docCategory').value=add.dataset.addDocCategory;return}if(e.target.id==='addDocRecord'){docRecordEditor();return}const edit=e.target.closest('[data-edit-doc]');if(edit){docRecordEditor(edit.dataset.editDoc);return}const del=e.target.closest('[data-delete-doc]');if(del){if(!confirm('Delete this document tracker entry?'))return;const next=docRecords().filter(x=>x.id!==del.dataset.deleteDoc);if(saveDocRecords(next)){Promise.all(['front','back','page',''].map(side=>photoOperation(del.dataset.deleteDoc+(side?'::'+side:''),'delete').catch(()=>{})));closeModal();render()}return}const saveButton=e.target.closest('[data-save-doc]');if(saveButton){if(saveButton.disabled)return;const title=document.getElementById('docTitle').value.trim(),issued=document.getElementById('docIssued').value,expiry=document.getElementById('docExpiry').value,category=document.getElementById('docCategory').value,err=document.getElementById('docEditorError');if(!title){err.textContent='Enter a document name.';return}if(issued&&expiry&&issued>expiry){err.textContent='Expiry date must not be before issue date.';return}const records=docRecords(),id=saveButton.dataset.saveDoc==='new'?'doc-'+Date.now()+'-'+Math.random().toString(36).slice(2,7):saveButton.dataset.saveDoc;const attachmentKind=document.getElementById('docAttachmentType').value;const item={id,title,category,issued,expiry,attachmentKind};const idx=records.findIndex(x=>x.id===id);if(idx>=0)records[idx]=item;else records.push(item);if(saveDocRecords(records)){saveButton.disabled=true;saveButton.textContent='Saving…';for(const [side,blob] of Object.entries(pendingDocPhotos)){try{await photoOperation(id+'::'+side,blob===null?'delete':'write',blob)}catch(e){alert('Document details were saved, but one attachment could not be saved. Please try again.')}}pendingDocPhotos={};closeModal();render()}return}if(e.target.id==='exportDocRecords'){const blob=new Blob([JSON.stringify({format:'toolbox2-document-tracker-v1',exportedAt:new Date().toISOString(),documents:docRecords()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='toolbox-document-tracker-backup.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return}});
document.addEventListener('click',e=>{if(e.target.id==='confirmBoarding'){const pct=readiness(state.voyage);openModal(`<h2>Confirm you're onboard?</h2><p>Your embarkation readiness is <strong>${pct}%</strong>. ${pct<100?'Some preparation items are unfinished. You can still confirm boarding.':'Your embarkation checklist is complete.'}</p><p>This will switch Home to Disembarkation Ready. Your original checklist remains available.</p><button class="btn full" id="completeBoarding">Yes, I'm Onboard</button>`);return}if(e.target.id==='completeBoarding'){state.voyage.boardingReadiness=readiness(state.voyage);state.voyage.stage='onboard';state.voyage.boardedAt=new Date().toISOString();save();closeModal();navigate('home');return}if(e.target.id==='confirmSignoff'){openModal(`<h2>Confirm sign-off?</h2><p>Disembarkation readiness is <strong>${progress(state.voyage.disembarkation)}%</strong>. Confirm only after you have actually signed off. Your checklist will be preserved until you start another voyage.</p><button class="btn full" id="completeSignoff">Yes, I've Signed Off</button>`);return}if(e.target.id==='completeSignoff'){state.voyage.stage='completed';state.voyage.signedOffAt=new Date().toISOString();save();archiveCompletedVoyage(state.voyage);closeModal();navigate('home');return}});
document.addEventListener('click',e=>{const accountPage=e.target.closest('[data-account-page]');if(accountPage){state.tab='account';navigate('account-'+accountPage.dataset.accountPage);return}if(e.target.closest('[data-account-back]')){state.tab='account';navigate('account');return}const accountGo=e.target.closest('[data-account-go]');if(accountGo){state.tab=accountGo.dataset.accountGo;navigate(state.tab);return}if(e.target.id==='closeCreateNotice'){closeModal();return}const createAction=e.target.closest('[data-create-action]');if(createAction){handleCreateAction(createAction.dataset.createAction);return}const historyButton=e.target.closest('[data-history-id]');if(historyButton){state.historyId=historyButton.dataset.historyId;navigate('voyage-history-detail');return}if(e.target.id==='closeQuickId'){closeModal();return}const qid=e.target.closest('[data-quick-id]');if(qid){quickIdDetail(qid.dataset.quickId);return}const docsection=e.target.closest('[data-doc-section]');if(docsection){state.tab='documents';navigate('doc-'+docsection.dataset.docSection);return}const learnItem=e.target.closest('[data-learn-open]');if(learnItem){learnOpen(Number(learnItem.dataset.learnOpen));return}const learnMode=e.target.closest('[data-learn-mode]');if(learnMode){document.querySelectorAll('[data-learn-mode]').forEach(b=>{const active=b===learnMode;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.learn-feature-action').forEach(x=>x.textContent=learnMode.dataset.learnMode==='exam'?'Open practice / exam →':'Open learning →');return}const rating=e.target.closest('[data-rating]');if(rating){localStorage.setItem('toolbox2-feedback-rating',rating.dataset.rating);render();return}const tab=e.target.closest('[data-tab]');if(tab){if(tab.dataset.tab==='create'){openModal(createMenu());return}state.tab=tab.dataset.tab;navigate(state.tab);return}const svc=e.target.closest('[data-service]');if(svc){const [g,i]=svc.dataset.service.split(':').map(Number);serviceDialog(g,i);return}const directory=e.target.closest('[data-directory]');if(directory){state.tab='home';navigate('directory-'+directory.dataset.directory);return}const link=e.target.closest('[data-link]');if(link){window.open(link.dataset.link,'_blank','noopener,noreferrer');return}const open=e.target.closest('[data-open]');if(open){navigate(open.dataset.open);return}const act=e.target.closest('[data-action]');if(act){closeModal();if(act.dataset.action==='new')navigate('voyage');else window.location.href='index.html';return}if(e.target.id==='startVoyage'){const months=+document.getElementById('months').value;state.voyage={vessel:document.getElementById('vessel').value.trim()||'Next Voyage',joining:document.getElementById('joining').value,months,...Object.fromEntries(Object.entries(defaults).map(([k,items])=>[k,items.map(([name,value])=>k==='packing'?{name,qty:Math.max(1,Math.ceil(value*months/6)),base:value,custom:false,done:false}:{name,done:value,na:false})]))};save();navigate('voyage');return}if(e.target.id==='editVoyage'){const p=state.voyage;openModal(`<h2>Edit Contract</h2><label class="field">Vessel<input id="editVessel" value="${escapeHTML(p.vessel)}"></label><label class="field">Joining date<input type="date" id="editDate" value="${escapeHTML(p.joining)}"></label><button class="btn full" id="saveContract">Save</button>`);return}if(e.target.id==='saveContract'){state.voyage.vessel=document.getElementById('editVessel').value;state.voyage.joining=document.getElementById('editDate').value;save();closeModal();render();return}if(e.target.id==='newVoyage'){openModal(`<h2>Start another voyage?</h2><p>Completed voyages are saved to Previous Voyages before starting again. An unfinished voyage will be replaced. History is stored on this device only.</p><button class="btn full" id="confirmNew">Replace Checklist</button>`);return}if(e.target.id==='confirmNew'){if(state.voyage?.stage==='completed'&&!archiveCompletedVoyage(state.voyage)){closeModal();return}state.voyage=null;save();closeModal();navigate('voyage');return}if(e.target.id==='addItem'){openModal(`<h2>Add checklist item</h2><label class="field">Item name<input id="itemName" maxlength="100"></label><button class="btn full" id="saveItem">Add item</button>`);return}if(e.target.id==='saveItem'){const name=document.getElementById('itemName').value.trim();if(!name)return;const id=state.page;state.voyage[id].push(id==='packing'?{name,qty:1,done:false}:{name,done:false,na:false});save();closeModal();render();return}for(const attr of ['qty','na','remove']){const b=e.target.closest(`[data-${attr}]`);if(!b)continue;const [a,c]=b.dataset[attr].split(':');const id=attr==='qty'?state.page:a;const i=attr==='qty'?+a:+c;if(attr==='qty'){state.voyage[id][i].qty=Math.max(0,state.voyage[id][i].qty+(+c));state.voyage[id][i].custom=true;}if(attr==='na')state.voyage[id][i].na=!state.voyage[id][i].na;if(attr==='remove')state.voyage[id].splice(i,1);save();render();return}});
document.addEventListener('change',e=>{if(e.target.id==='docPhotoInput'){const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf'].includes(file.type)){document.getElementById('docEditorError').textContent='Choose a JPG, PNG, WebP, HEIC or PDF file.';return}if(file.size>8*1024*1024){document.getElementById('docEditorError').textContent='Maximum attachment size is 8 MB.';return}pendingDocPhotos[activeDocSide]=file;showPhotoSelection(file);return}if(e.target.id==='docAttachmentType'){updateDocSlots();return}if(e.target.matches('[data-clock-zone]')){const sel=clockSelection();sel[e.target.dataset.clockZone]=e.target.value;localStorage.setItem(CLOCK_KEY,JSON.stringify(sel));refreshClocks();return}if(e.target.id==='accountReduceMotion'){localStorage.setItem('toolbox2-reduce-motion',String(e.target.checked));applyAccountPreferences();return}if(e.target.matches('[data-check]')){const [id,i]=e.target.dataset.check.split(':');state.voyage[id][+i].done=e.target.checked;save();render()}if(e.target.id==='months'&&state.voyage){state.voyage.months=+e.target.value;state.voyage.packing.forEach(item=>{if(!item.custom&&item.base)item.qty=Math.max(1,Math.ceil(item.base*state.voyage.months/6))});save();render()}});
document.addEventListener('input',e=>{if(e.target.id==='months'){document.getElementById('monthsLabel').textContent=`${e.target.value} months`}if(e.target.id==='search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.category-tile').forEach(b=>{const gi=Number(b.dataset.directory);b.hidden=!!q&&!serviceGroups[gi].title.toLowerCase().includes(q)&&!serviceGroups[gi].items.some(x=>x[0].toLowerCase().includes(q))})}if(e.target.id==='directorySearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('.service-list-card').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(q)})}});
document.getElementById('alerts').addEventListener('click',()=>openModal('<h2>Reminders</h2><p>Notifications will be added after the checklist and document systems are integrated.</p>'));
applyAccountPreferences();
render();
